/* ---------- Agenda ---------- */
.agx{padding:12px;display:flex;flex-direction:column;gap:8px}
.agx-h{display:flex;align-items:center;justify-content:space-between;padding:2px 4px}
.agx-h>div{display:flex;flex-direction:column;font-size:13.5px}
.agx-h b{font-weight:500}
.agx-h .muted{font-size:12px}
.agx-list{display:flex;flex-direction:column;gap:4px;position:relative}
.agx-e{display:grid;grid-template-columns:52px 3px 1fr;gap:10px;padding:8px 6px;border-radius:10px;text-align:left;width:100%;transition:background .2s,opacity .3s}
.agx-e:hover,.agx-e.open{background:var(--wash)}
.agx-e.past{opacity:.5}
.agx-e .tm{font-size:12px;color:var(--muted);padding-top:1px}
.agx-e .bar{border-radius:2px;background:var(--accent)}
.agx-e .t{display:flex;flex-direction:column;font-size:13px;min-width:0}
.agx-e .t b{font-weight:500}
.agx-e .t span{font-size:12px;color:var(--muted)}
.agx-e .who{display:flex;margin-top:6px}
.agx-e .who .av{width:20px;height:20px;font-size:8.5px;color:#fff;margin-right:-2px;box-shadow:0 0 0 1.5px var(--surface)}
.agx-e.open .who .av{box-shadow:0 0 0 1.5px var(--wash)}
.agx-prep{grid-column:3;font-size:12.5px;line-height:1.5;color:var(--fg2);display:flex;flex-direction:column;gap:5px;padding-top:8px}
.agx-prep div{display:flex;gap:7px;align-items:flex-start}
.agx-prep svg{color:var(--accent);margin-top:3px;flex:none}
.agx-now{display:flex;align-items:center;gap:6px;margin:2px 0;font-size:11px;color:var(--accent);font-weight:500;padding-left:6px}
.agx-now::after{content:"";flex:1;height:2px;background:var(--accent);border-radius:1px}
.agx-now i{width:7px;height:7px;border-radius:50%;background:var(--accent);animation:agnow 2s ease-in-out infinite}
@keyframes agnow{50%{box-shadow:0 0 0 5px var(--accent-bg)}}
.agx-join{margin-top:8px;align-self:flex-start}

DM.def('agenda', (r, c) => {
  const E = [
    ['9:00','Standup','15 min, Design team','b',[['MK','var(--pl)'],['JO','var(--pm)'],['AR','var(--pp)']],null,1],
    ['11:30','Agent demo','30 min, Zoom','y',[['SL','var(--pt)'],['MK','var(--pl)']],['Demo flow: pricing audit, then the token export','Sam asked about cost limits last time, the cap is now $5'],0],
    ['1:00','Pricing workshop','90 min, Room 4','p',[['JO','var(--pm)'],['AR','var(--pp)'],['DK','var(--pb)'],['MK','var(--pl)']],['Trial to paid is up 8.1 pts since Sep 18','Open question: show monthly price crossed out on mobile too?','3 frames ready to review in Figma'],0],
    ['4:00','1:1 with Maya','30 min','l',[['MK','var(--pl)']],['She wanted feedback on the checkout copy','Library publish is waiting on her approval'],0]
  ];
  const list = $('.agx-list', r);
  list.innerHTML = E.map((e, i) => `<button class="agx-e${e[6] ? ' past' : ''}" data-i="${i}"><span class="tm num">${e[0]}</span><span class="bar"></span><span class="t"><b>${e[1]}</b><span>${e[2]}</span><span class="who">${e[4].map(a => AV(a[0], a[1])).join('')}</span></span></button>`).join('');
  const rows = $$('.agx-e', list);
  rows[0].after(html('<div class="agx-now"><i></i>10:42</div>'));
  stagger([...list.children], 60);
  rows.forEach((el, i) => el.onclick = () => {
    const open = el.classList.contains('open'); rows.forEach(x => { x.classList.remove('open'); $('.agx-prep', x)?.remove(); });
    if (open || !E[i][5]) return;
    el.classList.add('open');
    const p = html(`<div class="agx-prep">${E[i][5].map(t => `<div>${I('spark','xs')}<span>${t}</span></div>`).join('')}${i === 1 ? '<span class="pill accent sm agx-join">Join in 48 min</span>' : ''}</div>`);
    el.appendChild(p); stagger([...p.children], 60);
  });
  c.later(1000, () => rows[2].click());
});
